    """Bubble each gate left past disjoint gates with a larger sort key.

    Returns the reordered list, or ``None`` when the sequence is already in
    canonical order. Only disjoint gates ever exchange positions, so the
    transformation (and its measurement semantics) is unchanged.
    """
    result = list(gates)
    moved = False
    for index in range(1, len(result)):
        gate = result[index]
        target = index
        while target > 0:
            blocker = result[target - 1]
            if blocker.qubit_set & gate.qubit_set or _sort_key(blocker) <= _sort_key(gate):
